import { Question } from '@/types/question';

const questions: Question[] = [
  { id: 'ai-engineer-model-eval-l4-001', language: 'ai-engineer', level: 'level4', category: 'Model Evaluation', subcategory: 'Calibration', question: 'What is Expected Calibration Error (ECE) and why is it important for deployed ML models?', options: ['Calibration only matters for binary classification', 'ECE should always be maximized', 'ECE bins predictions by confidence, then computes the weighted average gap between confidence and actual accuracy in each bin: ECE = Σ(n_b/N)|acc_b - conf_b|. A well-calibrated model\'s ECE is near zero, meaning when it says "90% confident," it\'s correct ~90% of the time. This is critical for: medical diagnosis (treatment decisions depend on prediction reliability), autonomous driving (action confidence thresholds), and any system where downstream decisions use prediction probability', 'ECE measures model accuracy'], correctAnswer: 2, explanation: 'ECE computation: (1) divide predictions into B bins by confidence (e.g., [0-0.1), [0.1-0.2), ..., [0.9-1.0]), (2) for each bin: compute average confidence and average accuracy, (3) ECE = Σ (n_b/N) · |accuracy_b - confidence_b|. Perfect calibration: ECE=0. Modern deep networks are typically overconfident (accuracy_b < confidence_b). Post-hoc calibration: temperature scaling (divide logits by T, fit T on validation set) is simplest and often sufficient. Platt scaling: fit sigmoid. Isotonic regression: fit monotonic step function. Reliability diagrams visualize calibration. For LLMs: calibration of verbalized confidence ("I\'m 80% sure") is a separate research area from logit calibration.', tags: ['ece', 'calibration', 'reliability-diagram', 'temperature-scaling'] },
  { id: 'ai-engineer-model-eval-l4-002', language: 'ai-engineer', level: 'level4', category: 'Model Evaluation', subcategory: 'Metrics', question: 'When should you use AUROC versus AUPRC for binary classification evaluation?', options: ['AUROC is always more informative than AUPRC', 'AUROC (Area Under ROC) is insensitive to class imbalance — a random classifier always scores 0.5 regardless of prevalence. AUPRC (Area Under Precision-Recall Curve) is sensitive to class imbalance and more informative when the positive class is rare (<5% prevalence). For fraud detection (0.1% fraud rate), a model with AUROC=0.99 might have AUPRC=0.10, revealing that most positive predictions are false positives. AUPRC should be the primary metric for imbalanced datasets', 'AUROC and AUPRC always give the same ranking of models', 'AUPRC is only used for multi-class problems'], correctAnswer: 1, explanation: 'AUROC: P(score(positive) > score(negative)) averaged over all positive-negative pairs. With 99.9% negatives: a model predicting 0.001 for everyone gets AUROC ≈ 0.5, which clearly indicates a useless model. But a model that catches 50% of fraud with 1% FPR gets AUROC = 0.97 — sounds great! AUPRC: precision at each recall threshold. That same model at 50% recall might have precision = 5% (catching 50 fraud out of 1000 flagged). AUPRC ≈ 0.05, revealing the operational reality. Rule of thumb: use AUROC when classes are roughly balanced or when you care about the overall ranking quality. Use AUPRC when the positive class is rare and precision at low recall matters (finding the fraud that matters, not ranking all transactions).', tags: ['auroc', 'auprc', 'class-imbalance', 'evaluation-metrics'] },
  { id: 'ai-engineer-model-eval-l4-003', language: 'ai-engineer', level: 'level4', category: 'Model Evaluation', subcategory: 'A/B Testing', question: 'What is the SUTVA (Stable Unit Treatment Value Assumption) and when is it violated in ML A/B tests?', options: ['Standard A/B tests account for all interference effects', 'SUTVA is always satisfied in online A/B tests', 'SUTVA violations only occur in medical experiments', 'SUTVA assumes each unit\'s outcome depends only on its own treatment assignment, not on others\' assignments. It is violated when: (1) marketplace effects (showing one user different recommendations affects what\'s available for others), (2) social network effects (treated user influences untreated friends), (3) shared resources (model variant A uses more GPU, slowing variant B). Violation means standard A/B test estimators are biased. Solutions: cluster randomization, switchback experiments, or graph-based experimental designs'], correctAnswer: 3, explanation: 'SUTVA violations in ML: (1) Two-sided marketplace (Uber, Airbnb): treating rider R with a new pricing model changes driver supply for all riders. (2) Social network (Facebook): treated user shares AI-recommended content with untreated users, affecting their behavior. (3) Inventory: recommendation model A promotes item X → sells out → model B cannot recommend it (shared inventory). Solutions: (a) cluster randomization: randomize at city/region level (geographically isolated units), (b) switchback experiments: alternate treatment over time (hour-by-hour), measuring within-unit effects, (c) two-wave experiments: first wave estimates interference, second wave adjusts for it. Violation leads to: underestimation of treatment effect (interference dilutes) or overestimation (positive spillover counted as treatment effect).', tags: ['sutva', 'ab-testing', 'interference', 'cluster-randomization'] },
  { id: 'ai-engineer-model-eval-l4-004', language: 'ai-engineer', level: 'level4', category: 'Model Evaluation', subcategory: 'Fairness', question: 'What are the three main definitions of fairness in ML and why are they mutually exclusive?', options: ['Three definitions: (1) Demographic parity: P(Ŷ=1|A=0) = P(Ŷ=1|A=1) (equal positive rate across groups), (2) Equalized odds: P(Ŷ=1|Y=1,A=0) = P(Ŷ=1|Y=1,A=1) AND P(Ŷ=1|Y=0,A=0) = P(Ŷ=1|Y=0,A=1) (equal TPR and FPR), (3) Predictive parity: P(Y=1|Ŷ=1,A=0) = P(Y=1|Ŷ=1,A=1) (equal precision). The impossibility theorem (Chouldechova 2017): when base rates differ between groups, you cannot simultaneously satisfy equalized odds and predictive parity except with a perfect or trivial classifier', 'Demographic parity is always the correct fairness definition', 'Fairness constraints never affect model accuracy', 'All fairness definitions can be satisfied simultaneously'], correctAnswer: 0, explanation: 'Impossibility theorem: if P(Y=1|A=0) ≠ P(Y=1|A=1) (different base rates, e.g., different disease prevalence), then no imperfect classifier can simultaneously satisfy equalized odds and predictive parity. Example: disease prevalence 10% in group A, 20% in group B. Equal FPR + equal TPR (equalized odds) → different positive predictive values (precision) between groups. Equal precision across groups → different FPR. You must choose which definition of fairness to optimize, and this is fundamentally a values question, not a technical one. The choice depends on context: criminal justice may prioritize equalized odds (equal error rates), lending may prioritize demographic parity (equal opportunity).', tags: ['fairness', 'impossibility-theorem', 'demographic-parity', 'equalized-odds'] },
  { id: 'ai-engineer-model-eval-l4-005', language: 'ai-engineer', level: 'level4', category: 'Model Evaluation', subcategory: 'LLM Evaluation', question: 'Why are static benchmarks insufficient for evaluating LLMs and what alternatives exist?', options: ['Static benchmarks suffer from: (1) data contamination (test questions leak into training data), (2) saturation (models score >90%, limiting discriminative power), (3) narrow task coverage (MMLU doesn\'t test instruction following, creativity, safety), (4) gaming (optimizing for benchmark format vs genuine capability). Alternatives: dynamic benchmarks (new questions per evaluation), human evaluation (expensive but gold standard), LLM-as-Judge with rubrics, arena-style comparisons (Chatbot Arena Elo ratings), and behavioral testing (CheckList, invariance tests)', 'Data contamination does not affect benchmark scores', 'LLMs should only be evaluated on perplexity', 'Static benchmarks perfectly measure LLM capabilities'], correctAnswer: 0, explanation: 'Benchmark limitations: MMLU was published in 2020; many questions have appeared in web training data since. Models can memorize answers without understanding. Chatbot Arena (LMSYS): users interact with anonymous model pairs, vote on preference → Elo rating. 500K+ human comparisons, continuously updated. Advantages: (1) no contamination (live conversations), (2) holistic (tests generation, not just MCQ), (3) community-driven. LLM-as-Judge (MT-Bench): GPT-4 scores responses on a rubric. 80% agreement with humans. Behavioral testing (Ribeiro et al. 2020 CheckList): test specific capabilities systematically — negation handling, temporal reasoning, numeric comparisons. Multi-faceted evaluation: combine benchmarks + human eval + behavioral tests for a complete picture.', tags: ['llm-evaluation', 'benchmarks', 'chatbot-arena', 'contamination'] },
  { id: 'ai-engineer-model-eval-l4-006', language: 'ai-engineer', level: 'level4', category: 'Model Evaluation', subcategory: 'Slice Analysis', question: 'What is slice-based evaluation and why can aggregate metrics hide model failures?', options: ['Aggregate metrics always capture all model failures', 'Only demographic slices need evaluation', 'Slice-based evaluation measures model performance on meaningful subgroups (demographics, data characteristics, business segments). A model with 95% overall accuracy might have 60% accuracy on a critical minority group, hidden by the majority group\'s high performance. Tools like SliceFinder automatically discover underperforming slices. For production ML: define critical slices upfront, set per-slice performance thresholds, and block deployment if any critical slice regresses', 'Slicing data always reduces statistical significance'], correctAnswer: 2, explanation: 'Example: sentiment classifier, 95% accuracy overall. Sliced: English 97%, Spanish 78%, code-switched text 45%. The aggregate hides critical failures. Slice definition: (1) demographic (gender, age, language), (2) data characteristic (text length, image quality, time of day), (3) business (high-value customers, new users, specific product categories), (4) model behavior (low confidence predictions, near decision boundary). Automated slice discovery: SliceFinder (Chung et al. 2019) uses decision trees to find subgroups with worst performance. Domino (Eyuboglu et al. 2022) uses embeddings to discover coherent error clusters. Per-slice monitoring in production: track metrics per slice over time, alert when any slice degrades.', tags: ['slice-analysis', 'subgroup-performance', 'slicefinder', 'disaggregated-evaluation'] },
  { id: 'ai-engineer-model-eval-l4-007', language: 'ai-engineer', level: 'level4', category: 'Model Evaluation', subcategory: 'Counterfactual', question: 'What is counterfactual evaluation for recommender systems and why is it necessary?', options: ['Recommender systems can be evaluated using standard train/test splits', 'Counterfactual evaluation estimates the performance of a new policy (recommendation model) using data collected by the old policy, without deploying the new model. This uses inverse propensity scoring (IPS): reweight logged data by the ratio of new/old policy probabilities. This enables safe offline evaluation of many model candidates before expensive online testing, though it suffers from high variance when the new and old policies differ significantly', 'Counterfactual evaluation always produces unbiased estimates', 'Online A/B testing is the only valid evaluation for recommenders'], correctAnswer: 1, explanation: 'The problem: standard offline evaluation (train/test split) is biased because the test set only contains items the old model recommended. If the new model would recommend different items, we have no outcome data for them. IPS estimator: V̂(π_new) = (1/N) Σ (π_new(a|x)/π_old(a|x)) · r, where π is the recommendation probability. If the new model recommends item A with probability 0.8 but the old model recommended it with probability 0.1, the reward is upweighted by 8x. Problems: (1) high variance (extreme weights when policies differ), (2) requires logging propensities (probability old model chose each action). Solutions: clipped IPS (bound the weight ratio), doubly robust estimator (combine IPS with a reward model for lower variance). This is standard practice at Netflix, Spotify, Amazon for pre-screening model candidates.', tags: ['counterfactual', 'ips', 'off-policy', 'recommender-evaluation'] },
  { id: 'ai-engineer-model-eval-l4-008', language: 'ai-engineer', level: 'level4', category: 'Model Evaluation', subcategory: 'Regression Metrics', question: 'What are the differences between MAE, MSE, RMSE, and MAPE and when should each be used?', options: ['MSE is always the best regression metric', 'MAPE works correctly when the target contains zeros', 'All regression metrics produce the same model ranking', 'MAE (mean absolute error): robust to outliers, interpretable in original units. MSE (mean squared error): penalizes large errors quadratically, useful when large errors are disproportionately costly. RMSE (√MSE): same units as target, comparable to MAE. MAPE (mean absolute percentage error): scale-independent, useful for comparing across different-scale targets, but undefined for zero values and biased toward underprediction. Choose based on: error distribution importance, outlier sensitivity requirements, and interpretability needs'], correctAnswer: 3, explanation: 'MAE = (1/N)Σ|y-ŷ|: median-optimal estimator, robust to outliers, gradient = sign(error). MSE = (1/N)Σ(y-ŷ)²: mean-optimal estimator, heavily penalizes outliers (error of 10 counts 100x vs error of 1). RMSE = √MSE: same units as y, directly comparable to MAE. If RMSE >> MAE, there are large outlier errors. MAPE = (100/N)Σ|y-ŷ|/|y|: percentage error, scale-independent but: (1) undefined when y=0, (2) asymmetric: overpredictions penalized less than underpredictions (predicting 150 for y=100: 50% MAPE, predicting 50 for y=100: 50% MAPE, but predicting 50 for y=200: 75% MAPE). Use: MAE for robust general-purpose, MSE/RMSE when large errors matter (financial loss), MAPE for comparing across different scales (revenue forecasts at different store sizes).', tags: ['mae', 'mse', 'rmse', 'mape'] },
  { id: 'ai-engineer-model-eval-l4-009', language: 'ai-engineer', level: 'level4', category: 'Model Evaluation', subcategory: 'Online Evaluation', question: 'What is the difference between interleaving experiments and traditional A/B tests for ranking evaluation?', options: ['Interleaving and A/B testing are identical methods', 'A/B testing is always more statistically sensitive than interleaving', 'Interleaving merges results from two rankers into a single list shown to every user, crediting clicks to the originating ranker. A/B testing splits users between rankers. Interleaving is 10-100x more statistically sensitive because the paired comparison (same user evaluates both) eliminates user-level variance. Use interleaving for: initial ranker comparison (fewer users needed). Use A/B testing for: full metric evaluation (revenue, retention) and when interleaving is infeasible (non-ranking features)', 'Interleaving requires double the traffic of A/B testing'], correctAnswer: 2, explanation: 'A/B test: 50% users see ranker A, 50% see ranker B. Compare aggregate CTR. Variance comes from user differences. Need: millions of queries for significance. Interleaving (Team Draft): for each query, combine results from A and B. Show merged list to the user. If user clicks result from A, credit A. Compare credit counts. Variance comes only from query-level randomness (which user saw is controlled). Radlinski & Craswell (2006) showed interleaving needs 50-100x fewer queries for same statistical power. Netflix uses interleaving for initial ranker screening, then A/B for full metric suite (engagement, retention, revenue).', tags: ['interleaving', 'ab-testing', 'ranking-evaluation', 'statistical-power'] },
  { id: 'ai-engineer-model-eval-l4-010', language: 'ai-engineer', level: 'level4', category: 'Model Evaluation', subcategory: 'NLG Metrics', question: 'Why are BLEU and ROUGE poor metrics for evaluating modern language generation, and what alternatives exist?', options: ['All automated metrics are equally unreliable', 'N-gram metrics capture semantic meaning perfectly', 'BLEU (n-gram precision) and ROUGE (n-gram recall) only measure surface-level overlap with references, missing: (1) semantic equivalence (paraphrases score 0), (2) fluency (grammatically wrong text can have high n-gram overlap), (3) factuality (hallucinated text matching n-grams scores well). Better alternatives: BERTScore (embedding similarity), BLEURT (learned metric), UniEval (multi-aspect), and LLM-as-Judge (GPT-4 with rubrics). Human evaluation remains the gold standard for open-ended generation', 'BLEU and ROUGE perfectly measure generation quality'], correctAnswer: 2, explanation: 'BLEU: precision of n-grams in generated text found in reference. "The cat sat" vs reference "A cat was sitting" → low BLEU despite identical meaning. ROUGE: recall-oriented (how much of reference is covered). Same problem. BERTScore: computes cosine similarity between BERT embeddings of generated and reference tokens, using greedy matching. Captures paraphrases and semantic similarity. BLEURT: trained regression model on human quality judgments. UniEval: multi-dimensional (coherence, fluency, relevance as separate scores). LLM-as-Judge: prompt GPT-4 with a rubric and examples. Correlates ~80% with human judgment. For production: use multiple metrics + periodic human evaluation. Automated metrics for CI/CD regression detection, human eval for quality assurance.', tags: ['bleu', 'rouge', 'bertscore', 'nlg-evaluation'] },
  { id: 'ai-engineer-model-eval-l4-011', language: 'ai-engineer', level: 'level4', category: 'Model Evaluation', subcategory: 'Robustness', question: 'What is the CheckList framework for behavioral testing of NLP models?', options: ['CheckList requires thousands of hand-written test cases', 'CheckList (Ribeiro et al. 2020) defines three test types: (1) MFT (Minimum Functionality): does the model handle basic capabilities? (simple positive/negative sentiment), (2) INV (Invariance): does the model maintain predictions under meaning-preserving changes? (replacing names should not change sentiment), (3) DIR (Directional): do known changes produce expected output changes? (adding "but it was terrible" should flip sentiment). These systematic tests reveal capability gaps that aggregate metrics miss', 'CheckList only tests model accuracy on standard benchmarks', 'Behavioral testing is only useful for sentiment analysis'], correctAnswer: 1, explanation: 'CheckList for a sentiment model: MFT: "This movie is great" → positive (basic capability). INV: "This movie is great" → "This film is great" → same prediction (synonym invariance). "John said this movie is great" → "Mary said this movie is great" → same prediction (name invariance). DIR: "This movie is great but the ending was terrible" → sentiment changes toward negative (negation directional). Template-based generation: "I {adverb} {loved/hated} the {noun}" with fill-in-the-blank templates generates thousands of test cases automatically. Failure discovery: BERT-base fails on 9% of simple negation tests ("not great") — a critical gap hidden by aggregate accuracy. Applied to: NER, QA, toxicity detection, summarization. Commercial adoption at Microsoft, Google for production model testing.', tags: ['checklist', 'behavioral-testing', 'invariance', 'nlp-testing'] },
  { id: 'ai-engineer-model-eval-l4-012', language: 'ai-engineer', level: 'level4', category: 'Model Evaluation', subcategory: 'Uncertainty', question: 'How should prediction uncertainty be evaluated and what metrics are used?', options: ['Uncertainty evaluation metrics: (1) ECE (Expected Calibration Error): gap between confidence and accuracy, (2) Brier score: mean squared difference between predicted probabilities and outcomes, (3) NLL (negative log-likelihood): measures how well the predicted distribution matches outcomes, (4) AUROC of uncertainty: using model uncertainty to discriminate correct from incorrect predictions (high uncertainty should correlate with errors). Reliability diagrams visually show calibration quality. Deep ensembles and MC Dropout provide uncertainty estimates that can be evaluated with these metrics', 'Uncertainty cannot be measured or evaluated', 'Only one metric is needed for uncertainty evaluation', 'Model confidence scores are always well-calibrated'], correctAnswer: 0, explanation: 'Comprehensive uncertainty evaluation: (1) Calibration: reliability diagram (x=confidence bins, y=accuracy). Perfect: diagonal line. ECE: average deviation from diagonal. (2) Sharpness: are the predictions confident? Sharp predictions are concentrated (low entropy), but only valuable if also well-calibrated. (3) Discrimination: AUROC where positive=correct prediction, score=confidence. High AUROC means the model "knows when it knows." (4) Proper scoring rules: Brier score = (1/N)Σ(p_i - y_i)², NLL = -(1/N)Σ y_i·log(p_i). Both are minimized by well-calibrated confident predictions. For selective prediction: evaluate accuracy vs coverage curve — as you reject low-confidence predictions, accuracy should increase. The area under this curve quantifies how useful the uncertainty estimates are for decision-making.', tags: ['uncertainty-evaluation', 'calibration', 'brier-score', 'selective-prediction'] },
  { id: 'ai-engineer-model-eval-l4-013', language: 'ai-engineer', level: 'level4', category: 'Model Evaluation', subcategory: 'Experimentation', question: 'What is the minimal detectable effect (MDE) and how does it determine A/B test sample size?', options: ['Power analysis is unnecessary for ML experiments', 'MDE is the smallest effect size an A/B test can reliably detect with given sample size, significance level (α), and power (1-β). N = 16σ²/(MDE)² for a two-sample test with α=0.05, power=0.80. Smaller MDE → need exponentially more samples. For ML models: a 0.1% accuracy improvement is real but detecting it requires millions of examples, while a 5% improvement needs only thousands. Pre-experiment power analysis determines if the test has sufficient samples to detect the expected improvement', 'Sample size does not affect the ability to detect effects', 'MDE is always fixed at 5% regardless of sample size'], correctAnswer: 1, explanation: 'Power analysis formula (two-sample z-test): N_per_group = (Z_α/2 + Z_β)² × 2σ² / δ² where δ = MDE, σ² = metric variance. For α=0.05 (Z=1.96), power=0.80 (Z=0.84): N = 2×(1.96+0.84)²×σ²/δ² = 15.7σ²/δ². Example: CTR baseline 5% (σ² ≈ 0.05×0.95 = 0.0475), want to detect δ=0.5% improvement. N = 15.7×0.0475/(0.005)² = 29,830 per group. For ML model A/B test: if model improvement is δ=0.1% CTR, need N = 15.7×0.0475/(0.001)² = 746,575 per group. This is why: (1) ML improvements are often small → need large tests, (2) variance reduction (CUPED) is critical → reduces σ² by 50%+ → halves required N, (3) choose metrics with lower variance (ratio metrics, user-level aggregation).', tags: ['mde', 'power-analysis', 'sample-size', 'ab-testing'] },
  { id: 'ai-engineer-model-eval-l4-014', language: 'ai-engineer', level: 'level4', category: 'Model Evaluation', subcategory: 'Retrieval', question: 'What is the difference between MRR, MAP, and NDCG for retrieval evaluation?', options: ['All three metrics produce identical rankings of retrieval systems', 'MRR (Mean Reciprocal Rank): average of 1/rank of first relevant result — evaluates finding one relevant result quickly. MAP (Mean Average Precision): average precision at each relevant position, averaged across queries — evaluates finding all relevant results with good ranking. NDCG (Normalized Discounted Cumulative Gain): weights results by graded relevance with position discount — evaluates ranking quality with non-binary relevance. Use MRR for QA (one answer), MAP for search with binary relevance, NDCG for search with graded relevance', 'MAP works with graded relevance scores', 'MRR considers all relevant documents equally'], correctAnswer: 1, explanation: 'For query with relevant docs at positions [1, 4, 7]: MRR = 1/1 = 1.0 (only cares about first relevant). AP = (1/3)(1/1 + 2/4 + 3/7) = (1 + 0.5 + 0.43)/3 = 0.643 (precision at each relevant position). If relevance grades are [3, 1, 2] at positions [1, 4, 7]: DCG@10 = 3/log2(2) + 1/log2(5) + 2/log2(8) = 3 + 0.43 + 0.67 = 4.10. IDCG@10 (ideal ordering [3,2,1] at positions [1,2,3]): 3/1 + 2/1.58 + 1/2 = 4.77. NDCG@10 = 4.10/4.77 = 0.86. Use: MRR for FAQ/QA (find the one answer), MAP for document retrieval with binary relevance labels, NDCG for web search with 5-level relevance judgments.', tags: ['mrr', 'map', 'ndcg', 'retrieval-evaluation'] },
  { id: 'ai-engineer-model-eval-l4-015', language: 'ai-engineer', level: 'level4', category: 'Model Evaluation', subcategory: 'Distribution Shift', question: 'How should ML models be evaluated for out-of-distribution (OOD) robustness?', options: ['OOD evaluation requires: (1) define realistic distribution shifts (temporal: future data, geographic: new regions, demographic: new user groups), (2) create shifted test sets (or use existing OOD benchmarks like ImageNet-C for corruption robustness), (3) measure performance degradation under shift, (4) test OOD detection capability (can the model recognize when input is OOD?). Metrics: accuracy gap (ID vs OOD), effective robustness (OOD accuracy vs ID accuracy across models), and AUROC of OOD detection', 'Models never encounter OOD data in production', 'In-distribution test set performance is sufficient for deployment', 'OOD evaluation only matters for image models'], correctAnswer: 0, explanation: 'OOD evaluation protocol: (1) ID test set: standard held-out data from same distribution as training. (2) Natural shift sets: later time periods, different geographies, different data sources. (3) Synthetic shifts: ImageNet-C (15 corruptions at 5 severity levels), text with typos/paraphrases, tabular with feature drift. (4) OOD detection test: include samples from completely different domains and test if the model assigns them high uncertainty. Metrics: (a) accuracy drop: acc_OOD / acc_ID — how much does performance degrade? (b) effective robustness: does the model maintain relative performance under shift? (c) OOD detection AUROC: can the model distinguish ID from OOD inputs? Production: monitor input distribution and alert when OOD rate exceeds threshold.', tags: ['ood', 'distribution-shift', 'robustness', 'evaluation-protocol'] },
  { id: 'ai-engineer-model-eval-l4-016', language: 'ai-engineer', level: 'level4', category: 'Model Evaluation', subcategory: 'Explainability', question: 'How should model explanations themselves be evaluated for quality?', options: ['SHAP values are always the correct explanation', 'Explanations only need to look convincing to users', 'Explanation quality metrics: (1) faithfulness — does the explanation accurately reflect the model\'s decision process? (perturbing important features should change the prediction), (2) stability — do similar inputs produce similar explanations? (3) completeness — do the highlighted features account for the full prediction?, (4) human comprehensibility — can users correctly predict model behavior from the explanation? These are evaluated via feature perturbation tests, stability under input noise, and user studies', 'Model explanations are always correct and need no evaluation'], correctAnswer: 2, explanation: 'Evaluating explanations: (1) Faithfulness: if features {A, B, C} are highlighted as important, masking them should significantly change the prediction. Metric: correlation between feature importance and prediction change when masked. (2) Stability: for inputs x and x\' that are similar (small perturbation), explanations should be similar. If changing one word flips the entire explanation, it\'s unstable. (3) Comprehensibility: user study — show explanation, ask users to predict model behavior on new inputs. High accuracy = good explanation. (4) Consistency across methods: if SHAP and LIME produce completely different explanations for the same input, at least one is wrong. Practical concern: explanations can be convincing but unfaithful (they look reasonable to humans but don\'t reflect the model\'s actual reasoning). Always validate with perturbation tests.', tags: ['explainability-evaluation', 'faithfulness', 'stability', 'user-study'] },
  { id: 'ai-engineer-model-eval-l4-017', language: 'ai-engineer', level: 'level4', category: 'Model Evaluation', subcategory: 'Generative', question: 'How should the quality of text generated by LLMs be evaluated across multiple dimensions?', options: ['Human evaluation is always too expensive for LLM assessment', 'A single quality score is sufficient for LLM evaluation', 'LLMs should only be evaluated on grammatical correctness', 'Multi-dimensional LLM evaluation: (1) Helpfulness — does the response address the user\'s need? (2) Harmlessness — does it avoid harmful content? (3) Honesty — is it factually accurate and transparent about uncertainty? (4) Coherence — is it logically structured and well-written? (5) Conciseness — does it avoid unnecessary verbosity? Each dimension requires separate evaluation methods: factuality can be verified against sources, helpfulness requires task-specific assessment, and safety requires adversarial testing. MT-Bench and AlpacaEval provide multi-dimensional evaluations'], correctAnswer: 3, explanation: 'Evaluation approaches per dimension: Helpfulness: task completion rate, user satisfaction scores, LLM-as-Judge with task-specific rubrics. Harmlessness: red-teaming attack success rate, toxicity classifier scores on outputs, safety benchmark pass rates. Honesty: factual verification against knowledge bases, hallucination rate (claims not supported by sources), calibration of expressed confidence. Coherence: perplexity (fluency proxy), human ratings, discourse structure analysis. Conciseness: length vs quality curves (does quality improve with length?). Production evaluation stack: automated metrics for regression detection (daily), LLM-as-Judge for detailed analysis (weekly), human evaluation for calibration (monthly), red-teaming for safety (quarterly). Each dimension may have different acceptable thresholds depending on the application.', tags: ['multi-dimensional-eval', 'helpfulness', 'factuality', 'llm-quality'] },
  { id: 'ai-engineer-model-eval-l4-018', language: 'ai-engineer', level: 'level4', category: 'Model Evaluation', subcategory: 'Statistical Testing', question: 'Why is the paired bootstrap test preferred over the independent t-test for comparing two ML models?', options: ['Bootstrap tests always require larger test sets than t-tests', 'Paired tests and unpaired tests give identical results', 'The paired bootstrap test: (1) pairs predictions from both models on the same test examples (controlling for example difficulty), (2) makes no distributional assumptions (unlike t-test assuming normality), (3) handles complex metrics (F1, BLEU) where variance formulas are unknown. It computes the test statistic (metric difference) on B bootstrap samples of the test set, providing a distribution-free confidence interval for the performance difference. This is more reliable than unpaired tests for model comparison', 'The independent t-test is always more appropriate'], correctAnswer: 2, explanation: 'Why paired: test examples have varying difficulty. Example 1 is easy (both models correct), example 2 is hard (both wrong). The paired test captures that the performance difference is consistent across examples, reducing variance. Paired bootstrap procedure: (1) for b=1..B: sample test indices with replacement, compute metric_A(b) and metric_B(b) on same sample, compute diff(b) = metric_A(b) - metric_B(b), (2) CI for difference: [percentile_2.5(diff), percentile_97.5(diff)], (3) p-value: fraction of bootstrap samples where diff has opposite sign to observed. Advantages over t-test: works for any metric (NDCG, BLEU, F1), no normality assumption, handles correlated test examples. Koehn (2004) and Berg-Kirkpatrick et al. (2012) established this as standard practice for NLP model comparison.', tags: ['paired-bootstrap', 'statistical-testing', 'model-comparison', 'confidence-interval'] },
  { id: 'ai-engineer-model-eval-l4-019', language: 'ai-engineer', level: 'level4', category: 'Model Evaluation', subcategory: 'Bias Detection', question: 'What is the disparity amplification problem and how should it be measured during model evaluation?', options: ['Bias measurement is only needed for models used in hiring', 'Models can only reproduce biases, never amplify them', 'ML models never amplify existing biases', 'Disparity amplification occurs when an ML model produces a larger performance gap between groups than exists in the training data. For example, if training data has 40%/60% gender representation in a profession, but the model predicts 20%/80%. Measurement: compare disparities in training data (ground truth) vs model predictions. If |predicted_disparity - data_disparity| > 0, the model amplifies bias. This should be checked for all protected attributes during evaluation to prevent deploying models that worsen existing societal inequities'], correctAnswer: 3, explanation: 'Amplification occurs because models learn correlations from the majority pattern and extrapolate: if 60% of doctors in training data are male, the model may predict 80% male due to: (1) spurious correlations (male names co-occur with medical terms), (2) majority bias in feature representations, (3) threshold effects (borderline cases default to majority). Measurement: for attribute A with values {a1, a2}: data_disparity = |P(Y|A=a1) - P(Y|A=a2)|, model_disparity = |P(Ŷ|A=a1) - P(Ŷ|A=a2)|. Amplification = model_disparity - data_disparity. Zhao et al. (2017) showed standard image captioning models amplify gender stereotypes by 1.5-2x. Mitigation: debiasing during training (balanced loss weighting), post-processing (calibrate per-group thresholds), and regular disparity auditing.', tags: ['disparity-amplification', 'bias-detection', 'fairness-audit', 'measurement'] },
  { id: 'ai-engineer-model-eval-l4-020', language: 'ai-engineer', level: 'level4', category: 'Model Evaluation', subcategory: 'Hallucination', question: 'How should hallucination in LLM outputs be detected and measured systematically?', options: ['Human review is the only way to detect hallucination', 'Hallucination cannot be detected automatically', 'Hallucination detection methods: (1) NLI-based: check if generated claims are entailed by the source using a trained entailment model (faithfulness), (2) self-consistency: generate multiple responses and check agreement (inconsistency indicates unreliability), (3) knowledge-grounded: verify facts against an external knowledge base, (4) LLM-as-Judge: prompt a capable model to identify unsupported claims. Hallucination rate = fraction of claims not supported by sources. For RAG: compare generated claims against retrieved passages to measure faithfulness', 'Hallucination only occurs in small language models'], correctAnswer: 2, explanation: 'Systematic hallucination measurement: (1) Claim decomposition: break response into atomic claims ("Paris is the capital of France", "It has 12 million residents"), (2) Verification: for each claim, check against provided context (faithfulness) or knowledge base (factuality). (3) Classification: supported (entailed by source), unsupported (not mentioned), contradicted (conflicts with source). (4) Metrics: faithfulness rate = supported / (supported + contradicted), hallucination rate = (unsupported + contradicted) / total. Tools: FActScore (Min et al. 2023): decomposes and verifies biographical claims. RAGAS faithfulness: uses LLM to extract claims and check support. SelfCheckGPT: consistency-based detection without reference (if the model gives different answers each time, the claim is likely hallucinated). Production: run hallucination detection asynchronously on a sample of responses, track hallucination rate as a key metric.', tags: ['hallucination-detection', 'faithfulness', 'factscore', 'claim-verification'] },
  { id: 'ai-engineer-model-eval-l4-021', language: 'ai-engineer', level: 'level4', category: 'Model Evaluation', subcategory: 'Cost-Quality', question: 'How should the cost-quality trade-off be evaluated for LLM-based applications?', options: ['Cost-quality evaluation plots quality metrics (accuracy, user satisfaction) against cost (tokens × price per token, latency). The Pareto frontier identifies models that are not dominated in both dimensions. Evaluation should compare: model sizes (7B vs 70B), quantization levels (FP16 vs INT4), and serving configurations (batch size, caching). A 7B model at 1/20th the cost of GPT-4 may achieve 90% of GPT-4 quality — whether this is acceptable depends on the use case', 'Quality is the only metric that matters; cost is irrelevant', 'The most expensive model is always the best choice', 'Cost and quality are always inversely proportional'], correctAnswer: 0, explanation: 'Cost-quality framework: evaluate each model variant on: (1) quality metrics (task accuracy, user preference in blind comparison), (2) cost metrics ($ per 1K queries, compute hours per 1K queries), (3) latency metrics (p50/p99 response time). Plot quality vs cost → Pareto frontier. Example: GPT-4o (quality: 92%, cost: $10/1K), GPT-4o-mini (quality: 87%, cost: $0.50/1K), Llama-3-8B self-hosted (quality: 83%, cost: $0.10/1K). For customer support chatbot: 87% quality at $0.50 might be optimal (quality above threshold, 20x cheaper). For medical QA: 92% quality at $10 is necessary (errors are costly). The evaluation must include the cost of errors — a cheaper model that causes more customer complaints may be more expensive overall.', tags: ['cost-quality', 'pareto-frontier', 'model-selection', 'trade-off'] },
  { id: 'ai-engineer-model-eval-l4-022', language: 'ai-engineer', level: 'level4', category: 'Model Evaluation', subcategory: 'Temporal', question: 'Why is temporal evaluation important for ML models and how should time-based splits be designed?', options: ['Random splits are always sufficient for evaluation', 'Temporal evaluation always produces worse metrics than random splits', 'Temporal evaluation uses time-based train/validation/test splits (train on past data, test on future data) to simulate real deployment conditions. This catches: (1) data leakage from future features, (2) concept drift (model performance degrades on newer data), (3) seasonal patterns (model fails during holidays/events). Design: multiple temporal folds (walk-forward validation) provide robust estimates of deployment performance. Models should be evaluated on how they perform on data from AFTER training, not data randomly mixed in time', 'Time-based splits only matter for time-series forecasting'], correctAnswer: 2, explanation: 'Random split problem: training on 2023 data but test includes January 2023 examples → model has seen February-December 2023 data during training → test performance is inflated because the model has "seen the future." Temporal design: train on 2022, validate on Jan-Jun 2023, test on Jul-Dec 2023. Walk-forward: repeat with sliding windows. This reveals: (1) how quickly the model degrades (compare performance on 1-month-ahead vs 6-month-ahead), (2) when retraining is needed (performance drops below threshold), (3) whether temporal features are informative (day-of-week, season). For production: continuously evaluate on newest labeled data to detect degradation. Temporal evaluation gap: difference between random-split accuracy and temporal-split accuracy indicates the degree of temporal leakage in random evaluation.', tags: ['temporal-evaluation', 'time-split', 'walk-forward', 'data-leakage'] },
  { id: 'ai-engineer-model-eval-l4-023', language: 'ai-engineer', level: 'level4', category: 'Model Evaluation', subcategory: 'Efficiency', question: 'What metrics should be used to evaluate ML model efficiency beyond accuracy?', options: ['Efficient models always sacrifice accuracy', 'Model size has no impact on deployment cost', 'Accuracy is the only metric that matters for model evaluation', 'Efficiency metrics: (1) FLOPs per prediction (computational cost), (2) latency (wall-clock time, including data transfer), (3) throughput (predictions per second), (4) memory footprint (GPU memory required), (5) model size (disk storage), (6) energy consumption (CO2 equivalent). Pareto-optimal evaluation: plot accuracy vs each efficiency metric. The best model maximizes accuracy per FLOP, per watt, or per dollar. This is increasingly important for edge deployment, cost optimization, and environmental sustainability'], correctAnswer: 3, explanation: 'Efficiency evaluation table: Model A (ResNet-50): 95% accuracy, 4.1 GFLOPs, 97MB, 5ms inference. Model B (EfficientNet-B0): 94.5% accuracy, 0.4 GFLOPs, 20MB, 2ms inference. Model B achieves 99.5% of Model A\'s accuracy at 10% of the compute — clearly better for most deployments. Metrics to report: accuracy/GFLOP, accuracy/parameter, accuracy/watt. For LLMs: tokens/second/dollar (throughput efficiency), quality/token (does each generated token contribute?), TTFT (time to first token for user experience). Environmental: ML training CO2 emissions are growing rapidly — reporting energy per experiment is becoming an ethical expectation. Papers With Code started requiring efficiency metrics alongside accuracy for benchmark submissions.', tags: ['efficiency', 'flops', 'pareto-optimal', 'green-ai'] },
  { id: 'ai-engineer-model-eval-l4-024', language: 'ai-engineer', level: 'level4', category: 'Model Evaluation', subcategory: 'Safety Evaluation', question: 'What is a model card and what information should it contain?', options: ['Model cards are optional marketing documents', 'Model cards (Mitchell et al. 2019) document: (1) model details (architecture, training data, version), (2) intended use (primary use cases, out-of-scope uses), (3) performance metrics (overall + per-subgroup), (4) limitations (known failure modes, distribution restrictions), (5) ethical considerations (bias analysis, fairness metrics), (6) training data details (sources, preprocessing, known biases). They serve as transparent documentation for model consumers, enabling informed decisions about whether a model is appropriate for a specific application', 'Model cards only list the model architecture', 'Model cards only need to list accuracy on one benchmark'], correctAnswer: 1, explanation: 'Model card sections (following Mitchell et al. 2019 + Google/Hugging Face extensions): (1) Overview: model name, version, date, developers. (2) Intended use: primary use cases (e.g., "text classification for English product reviews"), out-of-scope uses (e.g., "not for medical diagnosis"). (3) Training: data sources, size, preprocessing, known gaps. (4) Evaluation: metrics on standard benchmarks + disaggregated by demographic groups, data slices, and edge cases. (5) Ethical analysis: bias measurements, fairness metrics across protected attributes, potential harms. (6) Limitations: known failure modes, distribution restrictions, adversarial vulnerabilities. (7) Environmental impact: training compute, CO2 estimate. Hugging Face requires model cards for uploaded models. The EU AI Act mandates documentation for high-risk AI systems, making model cards a compliance requirement.', tags: ['model-card', 'documentation', 'transparency', 'responsible-ai'] },
  { id: 'ai-engineer-model-eval-l4-025', language: 'ai-engineer', level: 'level4', category: 'Model Evaluation', subcategory: 'RAG Evaluation', question: 'How does the RAGAS framework decompose RAG system evaluation?', options: ['RAG evaluation only needs to check retrieval recall', 'RAG evaluation only needs end-to-end accuracy', 'RAGAS requires human annotators for all evaluations', 'RAGAS evaluates four dimensions: (1) Faithfulness — does the answer only use information from retrieved context? (prevents hallucination), (2) Answer Relevancy — does the answer address the question? (prevents off-topic responses), (3) Context Precision — are the retrieved passages relevant? (evaluates retriever precision), (4) Context Recall — do retrieved passages cover all needed information? (evaluates retriever recall). Each metric is computed using LLM-as-Judge, enabling automated evaluation without human labels'], correctAnswer: 3, explanation: 'RAGAS (Es et al. 2023) pipeline: Given (question, retrieved_contexts, generated_answer, ground_truth_answer): (1) Faithfulness: extract claims from answer → for each claim, check if any retrieved context supports it → faithfulness = supported_claims / total_claims. (2) Answer relevancy: generate questions from the answer → compute similarity to original question → high similarity = relevant answer. (3) Context precision: for each retrieved passage, check if it\'s useful for answering → precision = useful_passages / total_passages. (4) Context recall: extract facts from ground truth → check which facts appear in retrieved context → recall = covered_facts / total_facts. Debugging: low faithfulness → generation problem (hallucination). Low context recall → retrieval problem (missing documents). Low context precision → retrieval noise (irrelevant documents). This decomposition enables targeted improvement of the weakest RAG component.', tags: ['ragas', 'rag-evaluation', 'faithfulness', 'context-precision'] },
  { id: 'ai-engineer-model-eval-l4-026', language: 'ai-engineer', level: 'level4', category: 'Model Evaluation', subcategory: 'Multi-Task', question: 'How should models be evaluated when they are expected to perform multiple tasks simultaneously?', options: ['Average performance across tasks is the only metric needed', 'Multi-task evaluation requires: (1) per-task metrics (each task may need different metrics), (2) task-weighted aggregate (weight by task importance/frequency), (3) Pareto analysis (is the model on the efficiency frontier across all tasks?), (4) negative transfer detection (does multi-task training hurt any individual task compared to single-task?), (5) task interference analysis (do improvements on task A degrade task B?). A multi-task model may have excellent average performance while failing catastrophically on a critical minority task', 'Multi-task models always perform better than single-task models', 'Task importance weighting is unnecessary for evaluation'], correctAnswer: 1, explanation: 'Multi-task evaluation framework: (1) Per-task: evaluate each task independently on its benchmark (NER F1, QA accuracy, sentiment accuracy). (2) Baseline comparison: compare each task against a single-task specialist model. Delta = multi_task_score - single_task_score. Positive delta = positive transfer. Negative delta = negative transfer/task interference. (3) Weighted aggregate: if NER is 3x more important than sentiment for business, weight accordingly. (4) Worst-case: report minimum normalized score across tasks — the model is only as good as its weakest task for deployment purposes. (5) Scaling curve: how does adding more tasks affect each task\'s performance? At what point does adding tasks start hurting? For LLMs: multi-task evaluation suites (HELM, BigBench) evaluate across 30+ tasks with per-task and aggregate reporting.', tags: ['multi-task-evaluation', 'negative-transfer', 'task-interference', 'weighted-aggregate'] },
  { id: 'ai-engineer-model-eval-l4-027', language: 'ai-engineer', level: 'level4', category: 'Model Evaluation', subcategory: 'Production', question: 'What is the difference between offline evaluation, online evaluation, and shadow evaluation?', options: ['Online evaluation should always come before offline evaluation', 'Offline evaluation: test on historical data before deployment (cheap, fast, but may not reflect production distribution). Online evaluation (A/B test): serve model to real users and measure business metrics (gold standard but risky and slow). Shadow evaluation: process live traffic with new model but serve old model\'s predictions (realistic evaluation without user risk). The evaluation progression should be: offline → shadow → online (A/B) → full deployment, with each stage validating the model under increasingly realistic conditions', 'All three evaluation methods are identical', 'Shadow evaluation is identical to A/B testing'], correctAnswer: 1, explanation: 'Evaluation progression: (1) Offline: evaluate on held-out test set, compute all metrics, compare against baseline. Gate: metrics must exceed thresholds. Cost: minimal (no production impact). Limitation: test set may not represent current production distribution. (2) Shadow: deploy alongside production model, process same requests, log predictions but don\'t serve them. Gate: shadow metrics within expected range, latency acceptable, no errors. Cost: double compute during shadow period. Benefit: tests with real production data and traffic patterns. (3) Online (A/B): serve to a percentage of users (1% → 10% → 50%). Gate: business metrics (revenue, engagement) not degraded with statistical significance. Cost: potential user impact if model is worse. Full cycle: 1-4 weeks. Automated pipelines: pass offline gates automatically, shadow for 3 days with automated metric comparison, A/B with automated significance testing.', tags: ['offline-evaluation', 'online-evaluation', 'shadow-evaluation', 'deployment-pipeline'] },
  { id: 'ai-engineer-model-eval-l4-028', language: 'ai-engineer', level: 'level4', category: 'Model Evaluation', subcategory: 'Benchmark Design', question: 'What makes a good ML evaluation benchmark and what are the common pitfalls?', options: ['Benchmarks never need to be updated once created', 'Benchmark size is the only important property', 'Good benchmark properties: (1) representative of real-world distribution, (2) diverse across difficulty levels and data characteristics, (3) large enough for statistical significance, (4) free from label errors and ambiguity, (5) resistant to gaming (can\'t be solved by shortcuts), (6) regularly updated to prevent contamination. Common pitfalls: annotation artifacts (spurious patterns that solve the task), dataset bias (NLI hypothesis-only baselines), saturation (models score >95%, losing discriminative power), and benchmark overfitting (community optimizes for specific benchmarks)', 'Any collection of examples serves as a good benchmark'], correctAnswer: 2, explanation: 'Pitfall examples: (1) NLI annotation artifacts (Gururangan et al. 2018): hypothesis containing "not" is almost always a contradiction → model learns this shortcut without understanding entailment. (2) Visual QA language bias: "What color is the banana?" → always "yellow" regardless of image → model ignores image. (3) SQuAD: answer is always a span in the passage → model learns span extraction, not comprehension. (4) MMLU contamination: published in 2020, many questions now appear in LLM training data → inflated scores. Good design: adversarial filtering (remove examples solvable by simple baselines), diverse data sources, dynamic benchmarks (generate new questions per evaluation), canary detection (embed known strings to detect if benchmark leaks into training).', tags: ['benchmark-design', 'annotation-artifacts', 'data-bias', 'evaluation-pitfalls'] },
  { id: 'ai-engineer-model-eval-l4-029', language: 'ai-engineer', level: 'level4', category: 'Model Evaluation', subcategory: 'Embedding', question: 'How should embedding model quality be evaluated for retrieval applications?', options: ['Embedding evaluation for retrieval: (1) retrieval benchmarks (BEIR, MTEB) — measure recall@k, NDCG@k across diverse query-document datasets, (2) transfer evaluation — test on tasks not seen during training, (3) STS (Semantic Textual Similarity) — correlation with human similarity judgments, (4) linear probing — train a linear classifier on frozen embeddings for classification tasks, (5) domain-specific evaluation — test on your actual query-document pairs. MTEB (Massive Text Embedding Benchmark) evaluates across 7 task types and 56+ datasets for comprehensive assessment', 'Cosine similarity between random pairs is sufficient', 'A single retrieval benchmark is sufficient for all use cases', 'Embedding models only need to be evaluated on STS'], correctAnswer: 0, explanation: 'MTEB (Muennighoff et al. 2023) evaluates embeddings across: (1) Classification (sentiment, topic), (2) Clustering (grouping similar documents), (3) Pair Classification (paraphrase detection), (4) Reranking (relevance scoring), (5) Retrieval (query→document), (6) STS (similarity scoring), (7) Summarization (summary relevance). For production retrieval: (a) evaluate on BEIR for general retrieval quality, (b) evaluate on your specific domain (if medical: evaluate on medical QA pairs), (c) test with your actual query patterns (short queries, long queries, keyword-style, natural language). Custom evaluation: collect (query, relevant_doc, irrelevant_doc) triples from your data → measure if embedding ranks relevant > irrelevant. This is the most predictive of production performance.', tags: ['embedding-evaluation', 'mteb', 'beir', 'retrieval-quality'] },
  { id: 'ai-engineer-model-eval-l4-030', language: 'ai-engineer', level: 'level4', category: 'Model Evaluation', subcategory: 'Regression Testing', question: 'What is regression testing for ML models and how should it be implemented?', options: ['ML regression testing ensures new model versions do not degrade performance on previously handled cases. Implementation: (1) maintain a curated "golden set" of critical examples with expected outputs, (2) run the golden set through each new model version, (3) flag any example where the new model performs worse than the previous version, (4) categorize regressions by severity (critical path examples vs edge cases), (5) require human review of regressions before deployment approval. This catches cases where improving aggregate metrics inadvertently breaks specific important examples', 'Regression testing is only needed for code changes, not model updates', 'ML models do not need regression testing', 'Improving overall accuracy guarantees no regressions on individual examples'], correctAnswer: 0, explanation: 'ML regression testing golden set: 500-2000 curated examples including: (1) high-value examples (queries from important customers, safety-critical inputs), (2) known edge cases (previously fixed failure modes), (3) representative samples per data slice/category, (4) adversarial examples (known attack patterns). For each new model: run golden set → compare to previous model\'s outputs → flag regressions. Severity classification: critical (safety/compliance-related regression), high (key business use case regression), medium (quality degradation on standard examples), low (edge case regression). Gate: zero critical regressions allowed, <2% high regressions, review and accept medium/low. Implementation: automate as CI/CD pipeline step. Store historical golden set results in a database for trend analysis. Update the golden set periodically with new failure modes discovered in production.', tags: ['regression-testing', 'golden-set', 'quality-gates', 'deployment'] },
  { id: 'ai-engineer-model-eval-l4-031', language: 'ai-engineer', level: 'level4', category: 'Model Evaluation', subcategory: 'Multimodal', question: 'How should vision-language models be evaluated and what benchmarks exist?', options: ['VLMs only need to be evaluated on image captioning', 'The same metrics work for vision-only and vision-language tasks', 'Standard image classification benchmarks are sufficient', 'VLM evaluation benchmarks: (1) VQAv2 (visual question answering), (2) MMMU (college-level multimodal reasoning), (3) TextVQA (reading text in images), (4) DocVQA (document understanding), (5) ChartQA (chart interpretation), (6) MathVista (visual math reasoning). Beyond benchmarks: evaluate on application-specific tasks (product image description, medical image analysis). Key challenges: evaluating open-ended visual descriptions requires LLM-as-Judge or reference-based metrics like CLIPScore since visual content has many valid descriptions'], correctAnswer: 3, explanation: 'VLM evaluation is multi-faceted: (1) Visual perception: can the model correctly identify objects, read text, understand spatial relationships? (test with VQAv2, TextVQA). (2) Visual reasoning: can it perform logical reasoning over visual content? (test with MMMU, MathVista). (3) Document understanding: can it extract information from structured documents? (test with DocVQA, ChartQA, InfographicsVQA). (4) Grounding: can it localize objects described in text? (referring expression comprehension). (5) Generation quality: for image captioning/description, evaluate detail, accuracy, and relevance (use CIDEr, CLIPScore, or LLM-as-Judge). (6) Safety: multimodal-specific safety tests (typographic attacks, harmful image understanding). Evaluation must cover all modality interactions, not just individual modalities.', tags: ['vlm-evaluation', 'multimodal-benchmarks', 'mmmu', 'visual-reasoning'] },
  { id: 'ai-engineer-model-eval-l4-032', language: 'ai-engineer', level: 'level4', category: 'Model Evaluation', subcategory: 'Continual', question: 'How should continuously trained (updated) models be evaluated to detect catastrophic forgetting?', options: ['Only performance on the latest data matters after model updates', 'Catastrophic forgetting cannot be detected through evaluation', 'Models trained on more data never forget earlier knowledge', 'Detect forgetting by evaluating on all previous task/data distributions after each training update: (1) maintain evaluation sets from each training phase, (2) after each update, run evaluation on all historical sets, (3) plot a "forgetting matrix" showing performance on each past distribution after each update. If accuracy on old distributions drops while new distribution improves, the model is forgetting. Mitigation: elastic weight consolidation, replay buffers, and progressive network expansion. Evaluation must include both new and historical performance simultaneously'], correctAnswer: 3, explanation: 'Forgetting matrix: rows = evaluation points (after update 1, 2, 3...), columns = test sets (original, update 1 data, update 2 data...). Entry [i,j] = performance after update i on data distribution j. Forgetting = max_k(score[k,j]) - score[i,j] for each distribution j. If this is large, the model forgot distribution j after update i. Continual learning evaluation protocol: (1) average accuracy = (1/T)Σ score[T, j] across all T distributions after final update, (2) backward transfer = (1/T)Σ (score[T,j] - score[j,j]) — negative means forgetting, (3) forward transfer = (1/T)Σ (score[j-1,j] - random baseline) — can past learning help future tasks? Production: maintain a fixed "anchor" test set that never changes, evaluate every model version on it, alert if performance drops below threshold.', tags: ['catastrophic-forgetting', 'continual-learning', 'forgetting-matrix', 'evaluation-protocol'] },
  { id: 'ai-engineer-model-eval-l4-033', language: 'ai-engineer', level: 'level4', category: 'Model Evaluation', subcategory: 'Structured Prediction', question: 'What evaluation challenges are unique to structured prediction tasks (NER, parsing, segmentation)?', options: ['Structured prediction challenges: (1) partial credit: "New York" predicted as just "York" — is this 0% or 50% correct? Entity-level F1 requires exact span match (strict), while token-level F1 gives partial credit. (2) Hierarchical labels: predicting B-PER instead of I-PER is different from predicting O. (3) Sequence validity: generated tag sequences may be invalid (I-PER after B-LOC). (4) Segmentation overlap metrics (IoU, Dice) have different sensitivity to boundary errors than pixel-level accuracy. Choose metrics that match the downstream application\'s sensitivity to different error types', 'Structured prediction uses the same evaluation as classification', 'NER evaluation only needs token-level accuracy', 'Accuracy is always the appropriate metric for structured prediction'], correctAnswer: 0, explanation: 'NER evaluation schemes: Strict match: both entity boundaries and type must be exact ("New York City" as ORG — correct only if the full span and type match). Relaxed match: any overlap with correct type counts as correct. Token-level: each token evaluated independently (high scores but misses entity structure). MUC-style: count correct entities, missing entities, spurious entities → precision, recall, F1. The choice matters: in a medical NER system, detecting "aspirin" even if the exact span is off by one character is much better than missing it entirely — relaxed matching is appropriate. For linking entities to a database, exact boundaries matter. For segmentation: IoU (intersection over union) penalizes both over- and under-segmentation. Dice coefficient is similar but more sensitive to small objects. Panoptic quality separates detection quality from segmentation quality.', tags: ['structured-prediction', 'ner-evaluation', 'span-matching', 'iou'] },
];

export default questions;
